// 1. Declare a variable and assign a value to it.
let playerName = 'Alice';
let playerScore = 25;

// 2. Use the variable by referencing its name.
console.log(playerName);
console.log(playerScore);

// Create the variable (Initialization)
let currentScore = 0;
console.log('Starting Score:', currentScore);

// Update the variable (Reassignment)
currentScore = 10;
console.log('Updated Score:', currentScore);

// Update it again
currentScore = 15;
console.log('Final Score:', currentScore);

// Declare a constant variable
const birthYear = 1995;
console.log(birthYear);

// If we try to change it, the engine throws an error.
// Uncommenting the line below will crash the program:
// birthYear = 1996;

// Creating a variable with var
var employeeName = 'John';
console.log(employeeName);

// var allows you to completely redeclare the variable
// without any warnings! (let and const would throw an error here)
var employeeName = 'Bob'; 
console.log(employeeName);

// 1. Undefined (Automatic)
let futureData;
console.log(futureData); // We didn't assign a value!

// 2. Null (Manual)
let emptyResult = null;
console.log(emptyResult); // We intentionally set it to nothing.

let a = 10;
let b = 5;

console.log('Sum:', a + b);
console.log('Product:', a * b);
console.log('Power:', 2 ** 3); // 2 to the power of 3

// Using parentheses to control the order of operations
let result = (10 - 3) * 2; 
console.log('Complex:', result);
